def format_metadata_text(item: dict) -> str:
    """
    F2001: 항목 1건의 메타데이터를 검색에 사용할 하나의 색인 텍스트로 구성합니다.
    """
    return (
        f"[여행지 메타데이터] 여행지명: {item['name']} | "
        f"국가: {item['country']} | 대륙: {item['continent']} | "
        f"테마: {item['theme']} | 예산 수준: {item['budget_level']} | "
        f"추천 여행 시기(베스트 시즌): {item['best_season']} | "
        f"요약 설명: {item['summary']}"
    )


def main():
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
        json.dump(TRAVEL_ITEMS, f, ensure_ascii=False, indent=2)
    print(f"[F2001 완료] 총 {len(TRAVEL_ITEMS)}건의 글로벌 여행지 메타데이터를 '{OUTPUT_FILE}'에 저장했습니다.")
    print(f"[샘플 색인 텍스트 (1번 항목)]:\n{format_metadata_text(TRAVEL_ITEMS[0])}")


if __name__ == "__main__":
    main()
